script.text:
			&OutlineEntry;
			/* <flatten type="Javascript"> */
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(f, 'ma_dvcs', true);
	if (f._costUnit) onChangeUnit(f.getItem('ma_dvcs2'));
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, k = new Array();
			var dFrom = new Date(f.getItemValue('nam'), f.getItemValue('ky1') - 1, 1), dTo = new Date(f.getItemValue('nam'), f.getItemValue('ky2'), 0);
			var ds1 = $func.formatDateOrder(dFrom), ds2 = $func.formatDateOrder(dTo);

			Array.add(k, {Name: 'ngay_hl_tu is null or ngay_hl_tu', Opr: '<=', Value: ds1, Type: 'String', Ignore: false});
			Array.add(k, {Name: 'ngay_hl_den is null or ngay_hl_den', Opr: '>=', Value: ds2, Type: 'String', Ignore: false});
			Array.add(k, {Name: 'ma_dvcs1', Opr: '=', Value: f.getItemValue('ma_dvcs2'), Type: 'String', Ignore: false});
			g.set_externalKey(k);

			if (f._costUnit) g._denyEdit = f._unitDenyEdit;
			g._p1 = f.getItemValue('ky1'), g._p2 = f.getItemValue('ky2'), g._y = f.getItemValue('nam'), g._u = ((f._unitCode) ? f.getItemValue('ma_dvcs2') : f.getItemValue('ma_dvcs'));
			g._alterTitle = [null, [['%s1', $func.trim(g._p1.toString()), true], ['%s2', $func.trim(g._p2.toString()), true], ['%s3', $func.trim(g._y.toString()), true]]];
			if (g._$k != null) g._$k = [];
			break;
		case 'Unit':
			f._unitDenyEdit = result[0].Value;
			break;
		default:
			break;
	}
}

function setObjectFilterVisible(f, c, b) {
	var o = f.getItem(c);
	o.field.AllowNulls = !b;
	if (b) {
		var grandNode = o.parentNode.parentNode;
		Sys.UI.DomElement.addCssClass(grandNode, 'Required');
		Sys.UI.DomElement.addCssClass(grandNode, f._id);
		if (!f._controlFocus) f._controlFocus = o;
	}
	else $common.setVisible(o.parentNode.parentNode.parentNode, false);
}
function setUnitFilterInformation(f) {if (f._unitCode) f.setItemValues('ma_dvcs2, ten_dvcs%l', [f._unitCode, f._unitName]);}
function onChangeUnit(o) {o.parentForm.request('Unit', 'Unit', ['ma_dvcs2'], o);}
/* </flatten> */
